draw((k,0)--(k,5),dashed);
} }

draw((0,0)--(4,0)--(4,5)--(0,5)--(0,0));

draw((0,1)--(4,0)--(2,5)--(0,1));

label("$A$",(0,1),W);
label("$B$",(4,0),SE);
label("$C$",(2,5),N);

label("I",(0.5,3.5));
